   .then(response => response.json())
   .then(data => {
        // Create the recipe list
        const recipeListHtml = data.recipes.map(recipe => {
            return `
                <li>
                    <a href="${recipe.url}">${recipe.name}</a>
                </li>
            `;
        }).join('');
        recipeList.innerHTML = recipeListHtml;
    });

// Load the care data
